select distinct SCENARIO_ID, SCENARIO_TYPE
from MR_SCENARIO_RULE

    STATUS = 'ACTIVE'


            and SCENARIO_ID in

                #{id}



            and SCENARIO_ID = #{scenarioIdList}

select SCENARIO_ID as SCENARIO_SET_CODE, SCENARIO_ID as SCENARIO_CODE, SCENARIO_NAME, SCENARIO_TYPE, CURVE_TYPE, CURVE_CODE, TERM_CODE, TERM_DAYS, SCENARIO_SHIFT_VALUE, SCENARIO_SHIFT_RULE from MR_SCENARIO_RULE
STATUS = 'ACTIVE'
and SCENARIO_ID in
#{id}
and SCENARIO_ID = #{scenarioIdList}
order by SCENARIO_ID, LINE_NO

select SCENARIO_ID as SCENARIO_SET_CODE, SCENARIO_ID as SCENARIO_CODE, SCENARIO_NAME, SCENARIO_TYPE, START_DATE, END_DATE, SCENARIO_NO, SCENARIO_NO as SCENARIO_NUMBER, JUNP_DAY_NO, INCREASE_DAYS, SCENARIO_SHIFT_RULE, CURVE_TYPE as RISKFACTOR_TYPE, CURVE_TYPE, CURVE_CODE, RISKGROUP_ID, TERM_CODE, TERM_DAYS from MR_SCENARIO_RULE
STATUS = 'ACTIVE'
and SCENARIO_ID in
#{id}
and SCENARIO_ID = #{scenarioIdList}
order by SCENARIO_ID, LINE_NO

select SCENARIO_ID as SCENARIO_SET_CODE, SCENARIO_ID as SCENARIO_CODE, SCENARIO_NAME, SCENARIO_TYPE, START_DATE, END_DATE, SCENARIO_NO, JUNP_DAY_NO, INCREASE_DAYS, SHOCK_TYPE, SCENARIO_SHIFT_RULE, CURVE_TYPE as RISKFACTOR_TYPE, CURVE_TYPE, CURVE_CODE, RISKGROUP_ID, TERM_CODE, TERM_DAYS from MR_SCENARIO_RULE
STATUS = 'ACTIVE'
and SCENARIO_ID in
