select
    'IR_SPOT' as CURVE_TYPE,
    RISKFACTOR_ID as CURVE_CODE,
    DATA_DATE,
    coalesce(TERM_CODE, cast(TERM_DAYS as varchar)) as TERM_CODE,
    coalesce(TERM_DAYS, 0) as TERM_DAYS,
    "value" as YIELD_RATE
from MR_RISKFACTOR_DATA

    RISKFACTOR_TYPE = 'IR_SPOT'


            and DATA_DATE between #{startDate} and #{endDate}


            and DATA_DATE = #{startDate}


            and DATA_DATE = #{endDate}




            and RISKFACTOR_ID = #{curveCode}


            and RISKFACTOR_ID in (
                select distinct CURVE_CODE
                from MR_SCENARIO_RULE
                where STATUS = 'ACTIVE'
                  and SCENARIO_ID = #{scenarioId}
                  and CURVE_TYPE = 'IR_SPOT'
            )

